typedef struct r_crbtree_node {
	struct r_crbtree_node *link[2];
	struct r_crbtree_node *parent;
	ut32 red;
	void *data;
} RRBNode;

typedef struct r_crbtree_t {
	RRBNode *root;
	size_t size;
	RRBFree free;
} RRBTree;

